<?php
/**
 * NovoTech machine finder — AI assistant endpoint.
 *
 * The search panel on every page sends the visitor's question here; this script adds the site's
 * machine catalogue (ai/catalogue.json, generated by the site build) to the prompt, calls the
 * Anthropic Messages API and returns the answer plus the ids of the recommended machines, which the
 * page turns into product cards.
 *
 * Setup on the web server: copy ai-config.sample.php to ai-config.php and put the API key in it.
 * Without a key the endpoint answers {"error":"not_configured"} and the page falls back to its
 * built-in keyword search.
 */
declare(strict_types=1);

header('Content-Type: application/json; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header('Cache-Control: no-store');

$config = __DIR__ . '/ai-config.php';
$cfg = is_file($config) ? (include $config) : [];
$API_KEY   = $cfg['api_key']   ?? '';
$MODEL     = $cfg['model']     ?? 'claude-haiku-4-5';
$MAX_TOK   = (int)($cfg['max_tokens'] ?? 900);
$RATE_N    = (int)($cfg['rate_limit'] ?? 40);        // requests per IP per window
$RATE_SECS = (int)($cfg['rate_window'] ?? 600);      // window length in seconds

function fail(string $code, string $msg, int $http = 200): void {
    http_response_code($http);
    echo json_encode(['error' => $code, 'message' => $msg]);
    exit;
}

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    fail('method', 'POST only', 405);
}
if ($API_KEY === '') {
    fail('not_configured', 'The AI assistant is not configured on this server yet.');
}

// ---- simple per-IP rate limit (file based; fine for a product site)
$ip = $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
$bucket = sys_get_temp_dir() . '/novotech-ask-' . md5($ip) . '.json';
$now = time();
$hits = [];
if (is_file($bucket)) {
    $hits = json_decode((string)file_get_contents($bucket), true) ?: [];
    $hits = array_values(array_filter($hits, static fn($t) => $t > $now - $RATE_SECS));
}
if (count($hits) >= $RATE_N) {
    fail('rate_limit', 'Too many questions in a short time — please try again in a few minutes.', 429);
}
$hits[] = $now;
@file_put_contents($bucket, json_encode($hits));

// ---- input
$raw = file_get_contents('php://input');
$in = json_decode((string)$raw, true);
if (!is_array($in) || !isset($in['messages']) || !is_array($in['messages'])) {
    fail('bad_request', 'Expected {"messages":[...]}', 400);
}
$messages = [];
foreach (array_slice($in['messages'], -12) as $m) {
    if (!is_array($m) || !isset($m['role'], $m['content'])) { continue; }
    $role = $m['role'] === 'assistant' ? 'assistant' : 'user';
    $content = trim(mb_substr((string)$m['content'], 0, 2000));
    if ($content === '') { continue; }
    $messages[] = ['role' => $role, 'content' => $content];
}
if (!$messages || end($messages)['role'] !== 'user') {
    fail('bad_request', 'The last message must be from the user.', 400);
}
// the API requires alternating roles starting with "user"
$clean = [];
foreach ($messages as $m) {
    if ($clean && end($clean)['role'] === $m['role']) {
        $clean[count($clean) - 1]['content'] .= "\n" . $m['content'];
    } else {
        $clean[] = $m;
    }
}
if ($clean[0]['role'] !== 'user') { array_shift($clean); }
$messages = $clean;
$pageSlug = isset($in['page']) ? preg_replace('/[^a-z0-9-]/', '', (string)$in['page']) : '';

// ---- catalogue
$catPath = __DIR__ . '/ai/catalogue.json';
if (!is_file($catPath)) {
    fail('no_catalogue', 'Catalogue file missing on the server.', 500);
}
$cat = json_decode((string)file_get_contents($catPath), true);
$lines = [];
foreach ($cat['families'] ?? [] as $f) {
    $models = [];
    foreach ($f['models'] as $m) {
        $parts = [];
        foreach ($m as $k => $v) {
            if ($k === 'name') { continue; }
            $parts[] = str_replace('_', ' ', $k) . ': ' . (is_array($v) ? implode('/', $v) : $v);
        }
        $models[] = $m['name'] . ($parts ? ' (' . implode('; ', $parts) . ')' : '');
    }
    $lines[] = "### " . $f['name'] . "\n"
        . "id: " . $f['id'] . " | brand: " . $f['brand'] . ($f['line'] ? " (" . $f['line'] . ")" : '') . " | category: " . $f['category'] . " | page: /" . $f['page'] . "\n"
        . ($f['headline'] ? "Capacity: " . $f['headline'] . "\n" : '')
        . "Models: " . implode(" · ", $models) . "\n"
        . "Summary: " . $f['summary'] . "\n"
        . "Features: " . implode("; ", $f['features']);
}
$catalogue = implode("\n\n", $lines);

$system = <<<TXT
You are the machine finder for NovoTech Machine Tools Inc. (Mississauga, Ontario, Canada — metalworking machinery supplier, phone +1 647 526 5510, email info@NovoTechMachineTools.com, hours Mon–Fri 9:00–17:00 Eastern). Visitors describe what they need to cut, bend or make; you recommend the most suitable machine(s) from NovoTech's catalogue below and explain briefly why.

Rules:
- Recommend ONLY machines that appear in the catalogue. Never invent models, prices, capacities or delivery times. If nothing fits, say so and suggest the closest option or that the visitor contact NovoTech.
- Pay attention to the numbers: the stock size the visitor cuts or bends must be within the machine's capacity (round, rectangular, miter capacities, bar diameter). Prefer the smallest machine that does the job with some margin, and mention when a larger model is the safer choice.
- Understand the levels of automation: manual/gravity feed (operator lowers the bow), semi-automatic (hydraulic descent, one cut per start, operator feeds material), automatic (machine feeds, cuts and counts), double-column (rigid twin-column bow for heavy stock). "Automatic angle cutting of tube" means an automatic saw with a miter head, etc.
- Two band saw lines: Bekamak = premium line (built in Turkey, heavier construction); NovoTech value line (BS-, TBK-, TGK- and GZ-series models) = NovoTech's own lower-priced line. When both fit, mention one of each unless the visitor said premium or budget.
- Answer in the language the visitor writes in. Keep answers short: 2–5 sentences plus a compact list of the recommended models with the one-line reason for each. Use inches first, millimetres in brackets. No marketing fluff.
- Every machine comes with a CSA-approved electrical panel, 600 V 3-phase (208/240/480 V on request), a 1-year warranty and spare parts and support from Mississauga, ON, Canada; NovoTech installs and trains across Canada. Mention this only when relevant.
- End EVERY answer with one line exactly in this form (ids from the catalogue, 0–4 entries, the best first): RESULTS: [{"id":"<family id>","model":"<model name or empty>"}]
- If the visitor asks for a quote or price, invite them to use the "Request a quote" form on the machine's page or to call/email NovoTech.

Catalogue:

$catalogue
TXT;

$payload = [
    'model' => $MODEL,
    'max_tokens' => $MAX_TOK,
    'system' => $system,
    'messages' => $messages,
];

$ch = curl_init('https://api.anthropic.com/v1/messages');
curl_setopt_array($ch, [
    CURLOPT_POST => true,
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_TIMEOUT => 60,
    CURLOPT_HTTPHEADER => [
        'Content-Type: application/json',
        'x-api-key: ' . $API_KEY,
        'anthropic-version: 2023-06-01',
    ],
    CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE),
]);
$res = curl_exec($ch);
$http = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
$err = curl_error($ch);
curl_close($ch);

if ($res === false || $http >= 400) {
    error_log('ask.php upstream error ' . $http . ' ' . $err . ' ' . substr((string)$res, 0, 300));
    fail('upstream', 'The assistant is temporarily unavailable. Please call +1 647 526 5510 or email info@NovoTechMachineTools.com.', 502);
}
$data = json_decode((string)$res, true);
$text = '';
foreach ($data['content'] ?? [] as $block) {
    if (($block['type'] ?? '') === 'text') { $text .= $block['text']; }
}
$results = [];
if (preg_match('/RESULTS:\s*(\[.*\])\s*$/s', $text, $m)) {
    $results = json_decode($m[1], true) ?: [];
    $text = trim(preg_replace('/RESULTS:\s*\[.*\]\s*$/s', '', $text));
}
$valid = [];
$ids = array_column($cat['families'], 'id');
foreach ($results as $r) {
    if (is_array($r) && isset($r['id']) && in_array($r['id'], $ids, true)) {
        $valid[] = ['id' => $r['id'], 'model' => isset($r['model']) ? mb_substr((string)$r['model'], 0, 60) : ''];
    }
}
echo json_encode(['answer' => $text, 'results' => $valid, 'model' => $MODEL], JSON_UNESCAPED_UNICODE);
